<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class Reception extends Model {protected $fillable=['supplier_id','warehouse_id','number','received_at','supplier_document_number','total','notes','created_by','document_type','invoice_series','invoice_number','delivery_note_number','commission_members','storekeeper','difference_notes','status','document_code','reception_series','stock_entry_date','currency','vat_included','delegate','vehicle','mentions','paid_now','paid_amount','payment_method','payment_reference']; protected $casts=['received_at'=>'date','stock_entry_date'=>'date','total'=>'decimal:2','vat_included'=>'boolean','paid_now'=>'boolean','paid_amount'=>'decimal:2']; public function supplier():BelongsTo{return $this->belongsTo(Supplier::class);} public function warehouse():BelongsTo{return $this->belongsTo(Warehouse::class);} public function items():HasMany{return $this->hasMany(ReceptionItem::class);} public function supplierPayments():HasMany{return $this->hasMany(SupplierPayment::class);} }
